import{_ as o,l as r,o as e,c as p,v as l,p as i,x as t,d as s,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"集合通信带宽模型","description":"","frontmatter":{"title":"集合通信带宽模型","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/collective-bandwidth-model.md","filePath":"llm/collective-bandwidth-model.md","lastUpdated":1789023840000}'),c={name:"llm/collective-bandwidth-model.md"};function m(b,a,A,E,B,N){const n=r("Mermaid");return e(),p("div",null,[a[1]||(a[1]=l('<h1 id="集合通信带宽模型" tabindex="-1">集合通信带宽模型 <a class="header-anchor" href="#集合通信带宽模型" aria-label="Permalink to &quot;集合通信带宽模型&quot;">​</a></h1><div class="epigraph"><p>集体时间不是「字节除以网卡标称」。先付启动延迟，再按算法效率付有效带宽；小消息活在 $\\alpha$ 区，大消息才摸到 $\\beta$ 区。</p><footer>—— Hockney 的 $\\alpha$–$\\beta$ 模型；集体算法分析见 Chan 等对 MPI 集合的经典整理</footer></div><p><a href="/llm/nccl-algorithms">上一课</a> 给出了库如何选环和树。本课把选择变成<strong>可算的时间</strong>：给定 \\(n\\) 字节、\\(N\\) 卡、链路延迟与带宽，All-Reduce / All-Gather / All-to-All 各该落在哪一段屋顶线上。缺口是定量，不是再列算法名。<a href="/llm/pretrain-comm">预训练通信</a> 写过 \\(T\\approx\\alpha+n\\beta\\)；本课把 \\(\\alpha\\)、\\(\\beta\\) 接到具体集体，并说明 busbw 与标称 Gb/s 差在哪。后课拓扑与拥塞处理 \\(\\beta\\) 不是常数的情况。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>网卡写 400 Gb/s，不等于 400 Gb/s 的梯度同步。集体算法有冗余与流水，有效带宽常写成 \\(\\frac{N-1}{N}\\) 一类因子；协议与 chunk 又吃掉一部分。更关键的是分区：消息小于某拐点时，时间几乎不随 \\(n\\) 降，因为全是 \\(\\alpha\\)——启动、同步、内核 launch、PCIe 门铃。张量并行的短 All-Reduce、MoE 小微批的 All-to-All，经常停在这个区。再买更胖的网卡，\\(\\beta\\) 变好，\\(\\alpha\\) 几乎不动，step 不变。</p><p>问题因此是：对每一种原语，写出 \\(T(n,N)\\) 的主导项，并用 <code>nccl-tests</code> 的 busbw 曲线把拐点测出来。没有拐点，并行网格是拍脑袋。</p><p><span class="marginnote">busbw 是 NCCL 测试里按算法理想因子反推的「总线带宽」，用来和链路规格比。algbw 是 \\(n/T\\)。两者都要看：algbw 接近应用，busbw 接近硬件是否吃满。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>点对点：\\(T \\approx \\alpha + n\\beta\\)，其中 \\(\\beta=1/B\\)，\\(B\\) 为该路径有效带宽（NVLink 一档，IB/RoCE 另一档）。</p><p>Ring All-Reduce：约 \\(T \\approx 2(N-1)\\alpha + 2\\frac{N-1}{N}n\\beta\\)。前项随 \\(N\\) 涨，后项接近 \\(2n\\beta\\)。大 \\(n\\)、中等 \\(N\\) 时第二项主导，这是环「带宽最优」的含义。</p><p>Tree All-Reduce：跳数 \\(O(\\log N)\\)，前项变成 \\(O(\\log N)\\,\\alpha\\)，数据项通常差于环（根附近不能把体积摊匀），除非层次化把跨节点 \\(n\\) 先除以每节点 GPU 数。</p><p>All-Gather / Reduce-Scatter：大约是 All-Reduce 数据项的一半，延迟项仍随算法的步数走。</p><p>All-to-All：数据项约 \\((N-1)m\\beta\\)（\\(m\\) 为每对净荷），延迟项依调度是 \\(O(N)\\) 或 \\(O(\\log N)\\)。没有 \\(\\frac{N-1}{N}\\) 那种「加完变少」。</p>',13)),(e(),i(d,null,{default:t(()=>[h(n,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20LR%0A%20%20N%5B%22%E6%B6%88%E6%81%AF%E5%A4%A7%E5%B0%8F%20n%22%5D%20--%3E%20CMP%7B%22%E7%9B%B8%E5%AF%B9%E6%8B%90%E7%82%B9%22%7D%0A%20%20CMP%20--%3E%7C%22n%20%E5%B0%8F%22%7C%20A%5B%22alpha%20%E4%B8%BB%E5%AF%BC%3A%20%E5%87%8F%E6%AC%A1%E6%95%B0%E6%88%96%E7%BC%A9%E7%BB%84%22%5D%0A%20%20CMP%20--%3E%7C%22n%20%E5%A4%A7%22%7C%20B%5B%22beta%20%E4%B8%BB%E5%AF%BC%3A%20%E7%9C%8B%E6%8B%93%E6%89%91%E4%B8%8E%E7%AE%97%E6%B3%95%E6%95%88%E7%8E%87%22%5D%0A%20%20B%20--%3E%20NV%5B%22NVLink%20%E5%9F%9F%22%5D%0A%20%20B%20--%3E%20NIC%5B%22%E7%BD%91%E5%8D%A1%20%2F%20Clos%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>工程上：对每个进程组（TP / DP / EP）用真实消息大小跑微基准，标出拐点。TP 组应落在 <a href="/llm/nvlink">NVLink</a> 的 \\(\\beta\\) 区或至少 \\(\\alpha\\) 可接受；DP 组允许跨节点，但要把 All-Reduce 与计算重叠，使暴露出来的 \\(T\\) 小于层计算。EP 组若 \\(m\\) 落在 \\(\\alpha\\) 区，先加微批或缩 EP 度，再升级网络。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(\\alpha\\) 来自软件栈与同步：NCCL 内核启动、FIFO、跨节点 RDMA 握手、以及集体的全局同步波。多进程组并发时，\\(\\alpha\\) 会变差，因为门铃与完成队列互相干扰。\\(\\beta\\) 来自链路与争用：同一 NVLink 域里 TP 与另一组 All-Gather 抢注入，有效 \\(B\\) 下降。模型里的 \\(B\\) 必须是<strong>该 step 同时在飞的集体之和</strong>下的剩余，而不是空载规格。</p><p>层次化改变的是代入公式的 \\(n\\) 与 \\(N\\)：节点内 \\(N_{\\mathrm{local}}\\)、\\(B_{\\mathrm{nvlink}}\\)；跨节点 \\(N_{\\mathrm{nodes}}\\)、\\(n_{\\mathrm{node}}=n/N_{\\mathrm{local}}\\)、\\(B_{\\mathrm{nic}}\\)。总时间是两段之和，不是用集群总卡数套一次环公式——那会严重高估跨节点环的 \\(\\alpha\\)。</p><p><span class="marginnote">通信 dtype 进入 \\(n\\)。BF16 梯度相对 FP32 减半；FP8 再减。数值协议必须在所有 DP 副本对齐，见预训练通信课。模型里改 \\(n\\) 之前，先确认这是配方允许的精度，不是网卡开关。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>\\(\\alpha\\)–\\(\\beta\\) 忽略拥塞与丢包：它是空载或轻度负载的一阶模型。下一课起的轨拓扑与拥塞控制处理 \\(\\beta\\) 随时间变的部分。也不要把 GPU 核内归约时间漏掉：极小消息时，本地加与同步可能比链路更贵。</p><p>不要用峰值 FLOPS 去除通信时间来「证明」重叠成功。重叠成功的判据是：step 时间 ≈ 计算屋顶线，而不是通信公式的 \\(T\\) 单独变小。公式用来决定并行维画在哪张图上，用来解释为何加带宽救不了 TP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>集体时间 = 延迟项 + 数据项；拐点以下加带宽无效。</li><li>环 All-Reduce 数据项约 \\(2\\frac{N-1}{N}n\\beta\\)；All-to-All 没有归约减体积。</li><li>层次化要分段套公式，禁止用总卡数套一次环。</li><li>用 nccl-tests 的 busbw 曲线标定每个进程组的拐点。</li><li>出处：Hockney \\(\\alpha\\)–\\(\\beta\\)；Chan 等对集合通信的算法分析；NCCL 测试指标。</li></ul>',10))])}const P=o(c,[["render",m]]);export{u as __pageData,P as default};
